import{_ as t,o as e,c as d,Q as a}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"Dinner at the Restaurant — Text Messages","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/practice/dialogues/07-claire-restaurant-messages.md","filePath":"en/more/maltese/practice/dialogues/07-claire-restaurant-messages.md"}'),r={name:"en/more/maltese/practice/dialogues/07-claire-restaurant-messages.md"},n=a('<h1 id="dinner-at-the-restaurant-—-text-messages" tabindex="-1">Dinner at the Restaurant — Text Messages <a class="header-anchor" href="#dinner-at-the-restaurant-—-text-messages" aria-label="Permalink to &quot;Dinner at the Restaurant — Text Messages&quot;">​</a></h1><p><strong>Scenario:</strong> Claire and her friend exchange text messages to confirm tonight&#39;s dinner at a restaurant: the meeting time, what to wear, and childcare arrangements. (Speaker labels are inferred from the dialogue context.)</p><h2 id="complete-dialogue" tabindex="-1">Complete Dialogue <a class="header-anchor" href="#complete-dialogue" aria-label="Permalink to &quot;Complete Dialogue&quot;">​</a></h2><p><strong>Friend:</strong> Waranofsinhar it-tajjeb, Claire. Għal illejla kollox sew?</p><p><strong>Claire:</strong> Waranofsinhar it-tajjeb. Iva għal-lejla kollox sew. Fit-tmienja u nofs hux?</p><p><strong>Friend:</strong> Eżatt, niltaqgħu fit-tmienja u nofs u nidħlu ġewwa l-ħanut.</p><p><strong>Friend:</strong> X&#39;ser tilbes?</p><p><strong>Friend:</strong> Ħa tilbes ġakketta?</p><p><strong>Claire:</strong> Qed ikun ftit bard u għalhekk naħseb nilbes ġakketta u flokk tas-suf.</p><p><strong>Friend:</strong> Tajjeb, nilbes bħalek mela. It-tifel se iġġibuh magħkom?</p><p><strong>Claire:</strong> Jien u r-raġel, it-tifel ser inħalluh m&#39;ommi.</p><p><strong>Friend:</strong> Tajjeb, niltaqgħu mela. Saħħiet.</p><p><strong>Claire:</strong> Iva, niltaqgħu. Saħħiet.</p><h2 id="sentence-by-sentence-translation-and-word-notes" tabindex="-1">Sentence-by-Sentence Translation and Word Notes <a class="header-anchor" href="#sentence-by-sentence-translation-and-word-notes" aria-label="Permalink to &quot;Sentence-by-Sentence Translation and Word Notes&quot;">​</a></h2><h3 id="_1-friend" tabindex="-1">1. Friend <a class="header-anchor" href="#_1-friend" aria-label="Permalink to &quot;1. Friend&quot;">​</a></h3><p><strong>Malti:</strong> Waranofsinhar it-tajjeb, Claire. Għal illejla kollox sew?</p><p><strong>Translation:</strong> Good afternoon, Claire. Is everything all right for tonight?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Waranofsinhar</td><td>afternoon</td><td><code>wara</code> (after) + <code>nofsinhar</code> (noon)</td></tr><tr><td>it-tajjeb</td><td>the good</td><td><code>tajjeb</code> with the definite article; greeting phrase &quot;good afternoon&quot;</td></tr><tr><td>Għal</td><td>for</td><td>Preposition</td></tr><tr><td>illejla</td><td>tonight</td><td><code>il-lejla</code></td></tr><tr><td>kollox</td><td>everything</td><td>Indefinite pronoun</td></tr><tr><td>sew</td><td>fine; well</td><td>Adverb</td></tr></tbody></table><h3 id="_2-claire" tabindex="-1">2. Claire <a class="header-anchor" href="#_2-claire" aria-label="Permalink to &quot;2. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Waranofsinhar it-tajjeb. Iva għal-lejla kollox sew. Fit-tmienja u nofs hux?</p><p><strong>Translation:</strong> Good afternoon. Yes, everything is fine for tonight. Half past eight, right?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Waranofsinhar it-tajjeb</td><td>good afternoon</td><td>Greeting phrase</td></tr><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>għal-lejla</td><td>for tonight</td><td>Contracted <code>għal</code> + <code>il-lejla</code></td></tr><tr><td>kollox sew</td><td>all fine</td><td>Fixed phrase</td></tr><tr><td>Fit-tmienja</td><td>at eight</td><td>Contracted <code>f&#39;</code> + <code>it-tmienja</code></td></tr><tr><td>u nofs</td><td>and a half</td><td>Half past the hour</td></tr><tr><td>hux</td><td>right? isn&#39;t it?</td><td><code>hu</code> + <code>x</code>, a tag question</td></tr></tbody></table><h3 id="_3-friend" tabindex="-1">3. Friend <a class="header-anchor" href="#_3-friend" aria-label="Permalink to &quot;3. Friend&quot;">​</a></h3><p><strong>Malti:</strong> Eżatt, niltaqgħu fit-tmienja u nofs u nidħlu ġewwa l-ħanut.</p><p><strong>Translation:</strong> Exactly, we&#39;ll meet at half past eight and go inside the shop.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Eżatt</td><td>exactly</td><td>Loanword <code>exact</code></td></tr><tr><td>niltaqgħu</td><td>we meet</td><td>First-person plural</td></tr><tr><td>fit-tmienja u nofs</td><td>at half past eight</td><td>Time expression</td></tr><tr><td>nidħlu</td><td>we enter</td><td>First-person plural</td></tr><tr><td>ġewwa</td><td>inside</td><td>Preposition</td></tr><tr><td>l-ħanut</td><td>the shop</td><td>Masculine noun with the definite article</td></tr></tbody></table><h3 id="_4-friend" tabindex="-1">4. Friend <a class="header-anchor" href="#_4-friend" aria-label="Permalink to &quot;4. Friend&quot;">​</a></h3><p><strong>Malti:</strong> X&#39;ser tilbes?</p><p><strong>Translation:</strong> What are you going to wear?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>X&#39;</td><td>what</td><td>Contracted form of <code>x</code></td></tr><tr><td>ser</td><td>going to</td><td>Future marker</td></tr><tr><td>tilbes</td><td>you wear</td><td>Second-person singular</td></tr></tbody></table><h3 id="_5-friend" tabindex="-1">5. Friend <a class="header-anchor" href="#_5-friend" aria-label="Permalink to &quot;5. Friend&quot;">​</a></h3><p><strong>Malti:</strong> Ħa tilbes ġakketta?</p><p><strong>Translation:</strong> Are you going to wear a jacket?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Ħa</td><td>going to</td><td>Colloquial future marker</td></tr><tr><td>tilbes</td><td>you wear</td><td>Second-person singular</td></tr><tr><td>ġakketta</td><td>jacket</td><td>Loanword</td></tr></tbody></table><h3 id="_6-claire" tabindex="-1">6. Claire <a class="header-anchor" href="#_6-claire" aria-label="Permalink to &quot;6. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Qed ikun ftit bard u għalhekk naħseb nilbes ġakketta u flokk tas-suf.</p><p><strong>Translation:</strong> It&#39;s a bit cold, so I think I&#39;ll wear a jacket and a wool sweater.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Qed</td><td>is (progressive)</td><td>Progressive marker</td></tr><tr><td>ikun</td><td>is; will be</td><td>Present of <code>kun</code>, used for the weather</td></tr><tr><td>ftit</td><td>a bit</td><td>Degree adverb</td></tr><tr><td>bard</td><td>cold</td><td>Noun</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>għalhekk</td><td>therefore</td><td><code>għal</code> + <code>hekk</code></td></tr><tr><td>naħseb</td><td>I think</td><td>First-person singular</td></tr><tr><td>nilbes</td><td>I wear</td><td>First-person singular</td></tr><tr><td>flokk</td><td>sweater; jersey</td><td>Loanword</td></tr><tr><td>tas-suf</td><td>of wool</td><td>Contracted <code>ta&#39;</code> + <code>is-suf</code></td></tr></tbody></table><h3 id="_7-friend" tabindex="-1">7. Friend <a class="header-anchor" href="#_7-friend" aria-label="Permalink to &quot;7. Friend&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, nilbes bħalek mela. It-tifel se iġġibuh magħkom?</p><p><strong>Translation:</strong> OK, then I&#39;ll wear the same as you. Are you bringing the child with you?</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tajjeb</td><td>OK; fine</td><td>Adjective</td></tr><tr><td>nilbes</td><td>I wear</td><td>First-person singular</td></tr><tr><td>bħalek</td><td>like you</td><td><code>bħal</code> + <code>-ek</code> (your)</td></tr><tr><td>mela</td><td>then; so</td><td>Discourse marker</td></tr><tr><td>It-tifel</td><td>the child</td><td>Masculine noun with the definite article</td></tr><tr><td>se</td><td>will</td><td>Future marker</td></tr><tr><td>iġġibuh</td><td>you bring him</td><td><code>iġġibu</code> + <code>-h</code> (him)</td></tr><tr><td>magħkom</td><td>with you</td><td><code>ma&#39;</code> + <code>-kom</code> (plural &quot;you&quot;)</td></tr></tbody></table><h3 id="_8-claire" tabindex="-1">8. Claire <a class="header-anchor" href="#_8-claire" aria-label="Permalink to &quot;8. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Jien u r-raġel, it-tifel ser inħalluh m&#39;ommi.</p><p><strong>Translation:</strong> My husband and I, we&#39;ll leave the child with my mother.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Jien</td><td>I</td><td>First-person pronoun</td></tr><tr><td>u</td><td>and</td><td>Conjunction</td></tr><tr><td>r-raġel</td><td>the husband</td><td><code>raġel</code> with the definite article</td></tr><tr><td>it-tifel</td><td>the child</td><td>With the definite article</td></tr><tr><td>ser</td><td>will</td><td>Future marker</td></tr><tr><td>inħalluh</td><td>we leave him</td><td><code>inħallu</code> + <code>-h</code> (him)</td></tr><tr><td>m&#39;ommi</td><td>with my mother</td><td>Contracted <code>ma&#39;</code> + <code>ommi</code> (my mother)</td></tr></tbody></table><h3 id="_9-friend" tabindex="-1">9. Friend <a class="header-anchor" href="#_9-friend" aria-label="Permalink to &quot;9. Friend&quot;">​</a></h3><p><strong>Malti:</strong> Tajjeb, niltaqgħu mela. Saħħiet.</p><p><strong>Translation:</strong> OK, then let&#39;s meet. Bye.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Tajjeb</td><td>OK</td><td>Adjective</td></tr><tr><td>niltaqgħu</td><td>we meet</td><td>First-person plural</td></tr><tr><td>mela</td><td>then</td><td>Discourse marker</td></tr><tr><td>Saħħiet</td><td>bye</td><td>Plural farewell from <code>saħħa</code></td></tr></tbody></table><h3 id="_10-claire" tabindex="-1">10. Claire <a class="header-anchor" href="#_10-claire" aria-label="Permalink to &quot;10. Claire&quot;">​</a></h3><p><strong>Malti:</strong> Iva, niltaqgħu. Saħħiet.</p><p><strong>Translation:</strong> Yes, we&#39;ll meet. Bye.</p><table><thead><tr><th>Maltese</th><th>English meaning</th><th>Notes</th></tr></thead><tbody><tr><td>Iva</td><td>yes</td><td>Affirmative response</td></tr><tr><td>niltaqgħu</td><td>we meet</td><td>First-person plural</td></tr><tr><td>Saħħiet</td><td>bye</td><td>Farewell</td></tr></tbody></table>',54),o=[n];function i(l,s,h,c,g,u){return e(),d("div",null,o)}const p=t(r,[["render",i]]);export{m as __pageData,p as default};
